{
  "measurement_needs": [
    "Viscosity as a function of temperature",
    "Thermal stability and degradation profile",
    "Phase transition temperatures"
  ],
  "objective_met": true,
  "recommendations": [
    {
      "instrument_id": "EQ21",
      "role": "primary",
      "technique": "Rotational Rheology",
      "why": "This rheometer can measure viscosity across a range of temperatures to determine if the polymer's flow behavior is consistent with your extrusion parameters.",
      "accessories_to_confirm": [
        "Parallel plate or cone-and-plate geometry",
        "Specific temperature control software settings"
      ]
    },
    {
      "instrument_id": "EQ17",
      "role": "supplementary",
      "technique": "Thermogravimetric Analysis (TGA)",
      "why": "TGA can determine if your polymer is undergoing thermal degradation at your chosen extrusion temperatures, which could unexpectedly alter viscosity.",
      "accessories_to_confirm": [
        "Platinum sample pans",
        "Nitrogen or air purge gas"
      ]
    },
    {
      "instrument_id": "EQ18",
      "role": "supplementary",
      "technique": "Differential Scanning Calorimetry (DSC)",
      "why": "DSC identifies glass transition or melting temperatures, helping to confirm if the polymer is fully transitioning to a melt state at your operating temperature.",
      "accessories_to_confirm": [
        "Hermetic aluminum pans",
        "Cooling accessory for sub-ambient scans"
      ]
    }
  ],
  "not_available": [],
  "clarifying_question": null,
  "summary": "To understand why your polymer remains viscous, you should perform rheological testing to map viscosity against temperature. Additionally, TGA and DSC are recommended to check for thermal degradation or incomplete phase transitions that might be occurring at your extrusion temperatures."
}

{
  "measurement_needs": [
    "viscosity at high shear rates",
    "thermal stability",
    "molecular weight distribution",
    "thermal transitions (melting, glass transition)"
  ],
  "objective_met": true,
  "recommendations": [
    {
      "instrument_id": "EQ17",
      "role": "primary",
      "technique_id": "thermogravimetric_analysis",
      "property_id": "thermal_stability",
      "technique": "Thermogravimetric analysis (TGA)",
      "why": "TGA determines if your polymer is degrading at the extrusion temperature, which can cause unexpected viscosity changes.",
      "accessories_to_confirm": [
        "sample pans",
        "purge gas supply"
      ]
    },
    {
      "instrument_id": "EQ18",
      "role": "primary",
      "technique_id": "differential_scanning_calorimetry",
      "property_id": "melting_temperature",
      "technique": "Differential scanning calorimetry (DSC)",
      "why": "DSC identifies the melting temperature and degree of crystallinity, helping to confirm if the material is fully molten at your processing temperature.",
      "accessories_to_confirm": [
        "suitable pans and lids",
        "pan press"
      ]
    },
    {
      "instrument_id": "EQ21",
      "role": "supplementary",
      "technique_id": "rotational_rheometry",
      "property_id": "viscosity_vs_shear_rate",
      "technique": "Rotational rheometry",
      "why": "While it cannot reach the high shear rates of an extruder, it can characterize the viscosity-temperature profile and yield stress at lower shear rates to help diagnose flow behavior.",
      "accessories_to_confirm": [
        "parallel plate or cone-and-plate measuring geometries"
      ]
    }
  ],
  "not_available": [
    {
      "technique_id": "capillary_rheometry",
      "technique": "Capillary rheometry",
      "why_useful": "This is the standard method for measuring viscosity at the high shear rates typical of industrial extrusion processes."
    },
    {
      "technique_id": "gel_permeation_chromatography",
      "technique": "Gel permeation / size-exclusion chromatography (GPC/SEC)",
      "why_useful": "Unexpectedly high viscosity can be caused by high molecular weight or broad molecular weight distribution, which GPC can quantify."
    }
  ],
  "clarifying_question": null,
  "summary": "To understand why your polymer is unexpectedly viscous, you should first check for thermal degradation using TGA and confirm the melting behavior with DSC. While rotational rheometry can provide useful viscosity-temperature data, please note that it cannot replicate the high shear rates of an extruder; for that, capillary rheometry would be the ideal technique, though it is not currently available in our list."
}

{
  "measurement_needs": ["compressive stiffness (Young's modulus) of a porous polymer scaffold"],
