      "accessories_to_confirm": ["compression platens", "appropriate load cell for the expected force range of the scaffold"]
    }
  ],
  "not_available": [],
  "clarifying_question": null,
  "summary": "The Instron 5967 (EQ15) is the appropriate instrument for determining the compressive stiffness of your scaffold. You will need to confirm the availability of suitable compression platens and a load cell calibrated for the expected stiffness of your specific porous material."
}

{
  "measurement_needs": [
    "compressive stiffness (compressive modulus) of a porous polymer scaffold"
  ],
  "objective_met": true,
  "recommendations": [
    {
      "instrument_id": "EQ15",
      "role": "primary",
      "technique_id": "compression_testing",
      "property_id": "compressive_modulus",
