{
  "measurement_needs": ["Cell viability", "Cell morphology and spreading within a 3D hydrogel matrix"],
  "objective_met": true,
  "recommendations": [
    {
      "instrument_id": "EQ07",
      "role": "primary",
      "technique": "Confocal Laser Scanning Microscopy (CLSM)",
      "why": "The inverted confocal microscope allows for deep optical sectioning through 3D hydrogels to visualize cell morphology and viability markers (e.g., Live/Dead staining) in three dimensions.",
      "accessories_to_confirm": ["Appropriate fluorescent viability dyes (e.g., Calcein AM/Ethidium homodimer)", "Glass-bottom imaging chambers or multi-well plates"]
    },
    {
      "instrument_id": "EQ08",
      "role": "primary",
      "technique": "Multiphoton Microscopy",
      "why": "Multiphoton excitation provides superior penetration depth for thick, scattering hydrogel samples compared to standard confocal imaging.",
      "accessories_to_confirm": ["Appropriate fluorescent viability dyes", "Glass-bottom imaging chambers"]
    },
    {
      "instrument_id": "EQ09",
      "role": "supplementary",
      "technique": "High-content epifluorescence imaging",
      "why": "Useful for rapid screening of multiple samples or time-lapse imaging of cell spreading, though it lacks the optical sectioning capability of confocal systems for thick 3D samples.",
      "accessories_to_confirm": ["Fluorescent viability dyes", "Multi-well plates"]
    }
  ],
  "not_available": [
    {
      "technique": "Light Sheet Fluorescence Microscopy (LSFM)",
      "why_useful": "LSFM would be ideal for imaging large 3D hydrogel constructs with minimal phototoxicity and high speed, which is often preferred for live-cell 3D studies."
    }
  ],
  "clarifying_question": null,
  "summary": "To assess cell viability and spreading within a 3D hydrogel, you should use confocal or multiphoton microscopy to perform optical sectioning of stained samples. The Leica SP8 systems (EQ07 and EQ08) are the best tools for this, as they can resolve cells deep within the matrix. Please ensure you have the appropriate fluorescent viability stains and compatible imaging vessels for your hydrogel constructs."
}

